    walletCaption: 'Google, Apple, Telegram, и-мэйл, SMS, эсвэл дамжуулагчаар бүртгүүлж түрийвчийг хэдэн товшилтоор үүсгэнэ. Хувийн түлхүүрийн удирдлага, асран хамгаалалт байхгүй: Та өөрийн хөрөнгийн бүрэн хяналтад байгаа бөгөөд бид хэзээ ч таны хөрөнгийг олж авахгүй.',
    accountsDesc: 'Дебубарт хэд хэдэн арга зам байдаг бөгөөд тэдний нэг нь ч танаас түрийвчийг аль хэдийн эзэмшихийг шаарддаггүй. Google, Apple, Telegram-тай холбогдон өөрийн имэйл хаяг эсвэл SMS-рүү илгээсэн код, гар утас, компьютер дээрээ нэвтрэх, эсвэл таны ашиглаж буй түрийвчийг холбосноор нэвтэрнэ үү. Түрийвчний замаас бусад бүх зүйл нь таны хувьд костюм бус түрийвчийг үүсгэдэг: түлхүүрийг барьж, бид асрамж авахгүй бөгөөд хийийг ивээн тэтгэдэг тул та уг эх токеныг худалдаж авахгүйгээр илгээх, зөвлөгөө өгч, цуглуулах боломжтой. Та зөвхөн гарын үсэг зурахдаа биш, харин анх ашиглахдаа түрийвчийг хамгаалахыг хүснэ.',
    accountsB1Desc: 'Google, Apple, Telegram, эхний бичлэгээс танд зориулагдсан болон байгалийн хийн түрийвч.',
    accountsB3Desc: 'МетаМаск, Солонгийн өнгийн хавтастай, Trust, Phantom эсвэл WalletConnect-ыг холбох, хаягаа батлахын тулд нэг удаа тэмдэг тавина уу. Хэрэв Ethereum хаягийг түүхгүй тул Phantom-д нэвтэрч орвол та Solana түрийвчээ нотолж болно. Түрийвч хэрэглэгч өөрсдийн хий төлдөг.',
    accountsB5Desc: 'Шинэ гишүүдийн жагсаалтад нэгдэж, шинэ гишүүдийн чипийг эхний гучин өдрийн туршид нэрээ авч явдаг хүн бүр таньж, хүлээн авах боломжтой. Шинэ гишүүдэд Тохиргооноос дараа дахин нээгдэж болох нэмэлт удирдамжийг санал болгож байна.',
    accountsB6: 'Пассверд:',
    accountsB6Desc: '"Хурууны хээтэйгээр үргэлжлүүл" гэж сонгоод нууц үгээ оруулна уу — и-мэйл байхгүй, утасны дугаар байхгүй, нууц үг байхгүй. Ижил passkey вэбсайт болон Android аппликейшн дээр ажилладаг.',
    accountsB7: 'Импортолгоо, хувийн мэдээллийг шилжүүлэх:',
    accountsB8: 'Орхих:',
    accountsB8Desc: 'Та өөрийн бүртгэлээ Тохиргооноос устгаж болно. Таны профайл, байршуулалт болон хадгалагдсан мэдээллийн хэрэгслийг нөөц хуулбар зэрэг нь устгаж, Apple-ийн холбоосоор нэвтэрч цуцлав. Нийтийн blockchain-д аль хэдийн бичигдсэн ямар нэг зүйл тэнд үлдэв.',
    uploadGallery: 'Нийтлэлийг нэгээс илүү хэд хэдэн зургийг авч болно: тэмдэггүйгээр дөрөв, Мегалодон дахь тэмдэгт бүрээс хорин болтол нэмэгдэж, зураг тус бүр 42.069 MB хүртэл байж болно. Зургийг байрлуулах, хөгжмийн зохиолч дээрээ зурах, бичихээс өмнө хүссэн дарааллаар нь чирж, эх файлыг бүрэн нягтрал, хавчих болон томруулан харахын тулд ямар ч зургийг бүтэн дэлгэцээр нээнэ үү.',
    labelComposerTools: 'Зохиогч хэрэгсэл:',
