    topUpCardDesc: 'Худалдан авалтын хуудас DeHub Pay дээр ажилладаг. Картаар төлөх, эсвэл өөр гинж дээр барьсан криптовалютаар төлж, таны хувьд хөрвүүлэгддэг. Хамгийн бага нь $ 0.50 байна. ЭТП, ам .долларыг мөн MoonPay-ээр картаар, таныг аль хэдийнэ асааж, аппликейшнд гарын үсэг зурсан шууд бичнэ. Худалдан авалт хийсний дараа нэг саванд хооллож болно.',
    badgeUnlock4: 'Супер хүч, профайл гоо сайхны бүтээгдэхүүн, илүү их профайл бодож байсны тоо, шуудан бүрт илүү олон зураг, өөрийн manokana эможи, наалт болон GIF багцууд.',
    tipDesc3: 'Типпүүд пост, коммент, зөвшөөрөлт хариулт, ажиллаж байгаа үйлдвэрлэлийн дунд нь ашиглагдаж байна. ДеХаб токенүүдээсээ хязгаарлагдсан байхад, типпүүдийн талбар нь үүнийгээ USDC, ETH, Base, BNB Chain, Robinhood Chain, Arc дэх ашигт баланс болон хуулбарлаж, типпээсээ өгөхөд хэрэглэдэг байна. Типпээсээ пост өгснөөр, типпээсээ өгсөн байгааг үзэхэд алтны хөхтөн хөмрөгт хүртэлсэн нүдтэй болно.',
    liveStreamDesc: 'Өөрийн браузер эсвэл кодлогч дээр бичлэг, хөгжмийн зохиолчоос шууд очно уу. Горхи нь DeHub-ийн өөрийн ingest-д нэвтэрч, WebRTC-г ойролцоо бодит цаг хугацаанд тоглуулах, Livepeer-тэй автомат уналтанд сүлжээнд хүрч чадахгүй үед хэвлэн нийтэлдэг. Горхи бүр зөвшөөрөлгүй бөгөөд цензурд тэсвэртэй, өөрийн чаттай бөгөөд төгссөн мөчид нь давталт болж хувирна.',
