    subsDesc: 'Бүтээгчид захиалга шууд өөрийн профайлаас зарна. Төлөвлөгөө нь ам .доллараар үнэтэй бөгөөд амьд үнээр ДеХубын жетон дээр төлдөг бөгөөд бүтээгчийн хувийг оронд нь түрийвчэндээ шууд төлдөг бөгөөд DeHub-ийн тэмдэгт хуваарилсан төлбөрийг хассан байна. Захиалагчийн зөвхөн бичлэгүүд бол жинхэнэ хаалга юм: бүртгүүлээгүй хүмүүс бичлэгийг бус, нэг шугамын хаалгыг хардаг.',
