    messagesDesc: 'Дебитийн шууд мессежүүд нь анхдагчаар төгсгөл хүртэл шифрлэгдсэн, монитор хийж, орчин үеийн мессенжерээс хүлээж буй хяналтыг дагалдаж болно. Текст илгээхээс өмнө таны төхөөрөмж дээр битүүмжилсэн, бүтээгчид хүмүүсийг мессежээр цэнэглэж, дэлгэцийн буланд яриа боомт хийж, ингэснээр та чатлаж байхдаа үзэх боломжтой болно.',
