    militaryGrade: 'Шифрлэгдсэн текст',
    militaryGradeDesc: 'Зурвасын текст болон тайлбарыг зөвхөн таныг болон нөгөө хүн бариултай төхөөрөмж дээр шифрлэдэг. Хэрэв нөгөө хүн шифрлэгдээгүй мессежүүдийг нээгээгүй бол оронд нь мессеж илгээгдэнэ.',
