    spDescTeamUp: 'Түрийвчний хүчийг долоон хүртэлх данстай хослуулна. Багцын хүн бүр багцын тэнцэл онгойлгох түгжээг өмсдөг бөгөөд энэ нь юу ч болдоггүй. Багийн гишүүд хувийн хэлбэртэй байж болох тул хүмүүс тэдэнтэй нэгдэхийг хүсээд, эзэн нь тэднийг зөвшөөрч байна.',
    feedsHomeDesc: 'Текст, зураг, нийтлэл, видео, аудио, шууд бичлэгийн холимог тэжээл. Таалагдсан, сэтгэгдэл, бичлэгүүд, ишлэл, хавчуурга, токен оруулга нь карт бүрт баригддаг бөгөөд бичлэгүүд нь ялгаруулж, цалин харагдах эсвэл2 жил үзэхийг тохируулж болно. Хэн ч үүнд услахгүйн тулд гэрийн тэжээл нь зохиогчийн бүрийн нийтлэлүүдийн өдөрт хязгаарлагдмал тооны бичлэгүүдийг агуулдаг. Мегалодоны мегадоны арван дөрвөн хүртэлх шатанд тэмдэггүй, нэг бүрээс дээш нь л давхцдаг. Бүх зүйл зохиогчийнх нь профайл болон дараах ангилалд харагдаж байна.',
    feedsSort: 'Ангилах & шүүх:',
    feedsSortDesc: 'Хамгийн сүүлд ангиллын таб дээр хамгийн түрүүнд ирж байгаа бөгөөд дараа нь оролцоотой байх, тэр дундаа ихэнх зөвлөмжүүд орно. Тэжээлийг шүүлтүүрээр оруулаад видеонууд аль хэдийн тэмдэглэгдэж, нуугдаж байгаа бөгөөд гэрийн дээд хэсэгт ямар ч амьд үе шатууд сууж болно.',
    feedsReactionsDesc: 'Арван урвал товчлуур шиг сууна: хайр, хүндлэл, халуун, 100, хэхэ, гунигтай, уйлах, шунахайрах, шунахайрах гэх мэт. Үүнээс бусад хүн бүр нийттэй адил нийтлэлд тооцдог. Түүнд таалагдахын тулд хоёр удаа бичлэгийг оруулаад, гурав дахин тохируулснаар үүнийг хайрлахад, хэн хариу үйлдэл хийгээд юугаар үзүүлсэн тавиурыг нээх товчийг дарна уу. Картан дээрх тэргүүлэгч дүрс нь бичлэгийг хамгийн их татсан хариу арга хэмжээ юм. Реакторын тэмдэг нилээд их ач холбогдолтой бөгөөд асуудалд хариу үйлдэл үзүүлсэн хүмүүс ч байсан. Тохиргоо дахь зүүн гартай горим нь товчлуурыг яг барны зүүн талд шилжүүлнэ.',
    feedsCommentsDesc: 'Бичлэг бүр өөрийн дуртай, дургүй, үзэл бодлын талаар санал бичдэг. Хариулах сэтгэгдэл дээр дарна уу. Зохиолч өөртөө хариу өгөхөд гүйлт нь тоон утас болдог. Бүтээгч нэг сэтгэгдэл өөрсдийн бичлэг дээрээ тавьж болно; дараа нь хэлхээ нь зүүгээр хүргэдэг, дараа нь төлсөн сэтгэгдэл Зангуу, дараа нь хамгийн их хаягтай таван сэтгэгдлүүд. Жүжигчид энгийн газрын горимыг шуудангаар асааж, уншигчдаас хамгийн хүчтэй цэгээс нь хариу өгөхөөсөө өмнө нөгөө талаас нь асууж болох бөгөөд тайлбарын хайрцагт AI товчлуур нь таны өнгийг шалгаж, хэв маягийг нь өөрчилж, засаж залруулах, дүрмийг өөрчлөх боломжтой. Өөрийн хуваалцах цэснээс аливаа сэтгэгдлийг тайлагнах боломжтой.',
    feedsMuteDesc: 'Ямар ч нийтлэл дээрх ¢ цэснээс зохиолчийг хаах эсвэл товшино уу. Тэднийг хоолноосоо нам гүмоор унагаж, цэвэрлэж болно; блоклох нь цаашид явагдаж, хажуу тийш нь ажиллана, мессежийг бас бууруулдаг.',
    feedsDub: 'Видео сануулга:',
