    workB7: 'Бонусын хуудас:',
    workB7Desc: 'Бүтээгдэхүүний бүх бонус нь дугаартай хуудас болон хуваарилалтын карттай байдаг, бонусын тухай мэдээлэл хэрэгжүүлэгчид танилцуулдаг, хэрэгжүүлэгчид ажилдаа баталгаажуулсандаа төлөхдөө, түүний түүхний хуудас нь өгөгдөлдээ холбоотой хувь хүнтэй холбоотой байдаг. Видео болон зурагт сурталчилгааны бонус нь танилцуулгаас өөртөө хэрэгжүүлэгддэг.',
