    aiSuiteCreditsDesc: 'Үүсгэлтийг DeHub tokens-д төлдөг. Сервер нь ажиллаж эхлэхээс өмнө ажлын үнийг иш татдаг, та нэг дамжуулалтыг зөвшөөрч, төлбөрийг гинж дээр баталгаажуулсаны дараа ажил эхэлнэ. Түрийвч бүр хамгийн бага зардалтай загвар дээр таван үнэгүй зургийг авдаг бөгөөд Бүтээгчийн хуудас дээрх долларын үнэлэгдсэн токенуудын үлдэгдэл нь түрийвчний гарын үсэггүйгээр ажлын байрны төлбөрийг хийдэг. Үе шатын шидэлтийг минут тутамд ижил хэлбэрээр тооцдог.',
    adsPortalDesc: 'Бизнесүүд өөрөө өөртөө үйлчлэх зар сурталчилгааны порталаар дамжуулан DeHub дээр кампанит ажил явуулж болно — кампанит ажил үүсгэж, Дебит токенс дээр дээд цэг, гүйцэтгэлийг хянах, зар сурталчилгаа нь тэжээлд оруулсан. Сэтгэгдлүүдийг ямар ч зар сурталчилгаа үзүүлэхээс өмнө ирдэг бөгөөд уншигчид цөөн тооны зар сурталчилгааг үзэхийг хүсэх боломжтой.',
