    arcadeDesc: 'Зоосон машин нь хөтчийн таб дотор DeHub дотор гүйдэг тоглоомын тавиур юм. Суулгаж авах, худалдаж авах юмгүй, тусдаа данс байхгүй: нээж тогло. Өнөөдрийн зургаан цол хөлөг онгоц — Хааны Гамбит, онлайн Ило шат бүхий кино театрын 3D шатны тоглоом; Таны машин дээр торон, бүтэцтэй, дуу чимээ бүрийг бий болгодог Duty Клод; Jungle Trail, эхний хүн процедуроор үүссэн борооны ой модны дундуур алхдаг; Гудамжны шигтгээ, хажуугийн цохилт \'em босгосон for DeHub; Таны алхаж болох Chartopia, худалдааны шалан дээр WebXR-аар дамжуулан ширээний мониторууд болон VR горимд амьд зах зээлийн тэжээлтэй; Бурханы нүд болох 3D дэлхийд та DeHub нийгэмлэгийн дунд өөрийгөө ойролцоогоор хувилбараар байрлуулах боломжтой. Хөгжүүлэгчид өөрсдийн тоглоомыг хянах боломжтой.',
