    settingsB6Desc: 'Өөрийн чатыг экспортлох, өгөгдлийг задлах, бүртгэлд гарын үсэг зурсан төхөөрөмж болон сессийг шалгах, хиймэл оюун ухааны системүүд ажил дээрээ сургах эсэхээ сонгож (асаах боломжгүй), бүртгэлээ устга.',
    settingsB7: 'Холбоотой хэсэгүүд ба ашиглалтууд:',
