    accountsB4Desc: 'Тохиргооны → профайл болон унтраах болон буцахгүйгээр хэд хэдэн дансны талыг хажуугаар нь хадгална уу. Та пайзныхаа дэвсгэрийг хэдэн хүн барьж чадахаа шийддэг.',
