    accountsDesc2: 'Нэг хүн ижил хөтөчөөс хэд хэдэн заншлыг ажиллуулж чадна. Профайлуудыг Тохиргооны → Профайлд удирддаг: данс нэмж, тэдгээрийн хооронд шилжих, DeHub нь бүх сессийг хувиргадаг — түрийвч, тэжээл, мессеж, мэдэгдэл — нэг алхмаар. Профайлыг нэмэх нь таныг хэзээ ч танаас ирэхгүй бөгөөд таны байгаа газарт буцаж дуусгаж чадахгүй свичийг нэмнэ. Таны стейт тэмдэгтээр жагсаалтын хэмжүүрт хэдэн профайл зогсож болох вэ.',
    allowanceBadgeNote: 'Шигтгээ хоёуланг нь нэг дор хөдөлгөдөг — илүү том чөлөөт тэтгэмж, өнгөрсөн зүйлд хямд үнээр буурна. Хөнгөлөлт гэдэг нь DeHub жетоныг худалдаж авахад 5% -аас 30% -иас Мегалодон дээр хөнгөлөлт юм. Таны тэтгэмж таны олсон тэмдэгээс үүдэлтэй: асрагч таньд таны профайл дээр харуулав. Гэхдээ энэ нь танд тэдний шуудангийн тэтгэмжийг өгөхгүй.',
    allowanceCounts2: 'Видео, зураг, аудио бичлэгүүд нь өгөгдлийн тэтгэмжийн эсрэг файлын хэмжээгээрээ зарцуулдаг. Тэдгээрийг хадгалж, үйлчилдэг тул өнгөц зургууд багтсан.',
    allowanceCounts3: 'Үнийн санал өгөх бичлэгүүд нь дараах бичлэгтэй яг адилхан тоологддог: хавсаргасан видео бүхий ишлэл өгөгдөл.',
    allowanceCounts4: 'Томоохон хэмжээ нь pro-rata, бүтэн гигабайт хүртэл хураагдаагүй юм. Хэрэв байршуулах 200 MB таны тэтгэмжийг давсан тохиолдолд 200 MB-г төлнө.',
    allowanceHowDesc: 'Захиалга чухал бөгөөд энэ нь зориудаар: Та нийтлэгдээгүй нийтлэлийг төлөхгүй бөгөөд дараа нь зөвхөн том файлыг байршуулахгүй.',
    allowanceStep1: 'Апп нь өдөр бүрийнгээсээ өгсөн үнэтэй харьцуулж, өгсөн арвийнхээ хэрэглэх эрхтэй байгааг тодорхойлох бөгөөд хэрэгцээтэйгээр хэрэгжүүлэгдэнэ. Үүнийгээр мөнгө гаргагдахгүй, мэдээлэл уншихгүй байна.',
