    appsB3Desc: 'Тусдаа шилжих алхамгүйгээр ижил нэвтрэх, түрийвч, тэмдэг, тэнцэл.',
    arcadeDesc2: 'Тэдгээрийн хоёр нь гадаад үзэмжийн сэдэв дотор нуугдана: апп-г дайн руу тохируулаад Duty-ийн Клодыг сэдвээс нь хүлээн авах боломжтой бөгөөд Jungle Trail-ыг нуудаг. Хааны Gambit, Street Slayer нь манлайллын самбаруудтай байдаг бөгөөд тоглоом бүр өөрийн хувь карттай тул хаана ч байрлуулсандаа тохирохгүй байна.',
