    tvRadioDesc: 'Бүтээгчийн байршуулалтаас гадна DeHub хөлөг онгоц нь үргэлж зугаа цэнгэлийн гадаргуу дээр байдаг тул аппыг нээсэн мөчид үзэх, сонсох ямар нэг зүйл байна. Эдгээр нурууны туршлага тасралтгүй явагдаж, хөвөгч тоглогчдоор дамжуулан бүтээгдэхүүний эргэн тойронд дагаж явдаг тул хэвлэл мэдээллийн хэрэгсэл нь хаа нэгтээ чиглэсэн үед хэзээ ч зогсдоггүй.',
    walletHubB1Desc: 'ETH, BnB, USDT, USDC болон бусад суурь, BnB Chain, Ethereum, Robinhood Chain and Arc зэрэг олон гинжин түрийвчийг барьсан. Тэг үлдэгдэл нуугдсан бөгөөд апп хаяг хуулахаасаа өмнө аль сүлжээг асуухаас асууна. Хүлээн авах, илгээх, Худалдан авах, Худалдан авах, Сүйтгэх, Гүүр, Мөнгөн Гарах нь бүгд балансаас нэгийг нь холбох юм.',
    walletHubB2Desc: 'Үүсгэн байгуулагчийн санхүүжилтийн хяналтын самбар нь орлогын график, гүйлгээний зөрчил, хөндлөн гинжит шургуулгатай.',
    walletHubDesc: 'Дебабар бүр нь суурилуулсан, костюм бус түрийвчтэй хамт ирдэг. Хөтчийн суулгах өргөтгөлүүд байхгүй бөгөөд удирдах үрийн хэллэгүүд алга: түрийвчийг анх удаагаа танд нэвтэрч, баталгаажуулсан бөгөөд энэ нь апп доторх үнийн дүнгийн дамжуулалт бүрийг татан авч, цалин хөлс болон цалингийн дүнгээс татан авч, захиалга, усан үзэмж, бүтээгчийн орлогыг онгойлгоно. Өөр хэрэглэгчийн жетон илгээх нь үнэ төлбөргүй бөгөөд abstraction хэрэгсэл нь ихэнх хэрэглэгчид түүхий түрийвчний хаяг эсвэл хувийн түлхүүрд огт хүрч чадахгүй гэсэн үг юм.',
    workB2Desc: 'Нээлттэй утгуудыг үзэх, категори эсвэл валютаар шүүх, хүссэн хүнээ хэлж, шагнал цуглуулахын тулд ажлаа оруулна уу. Хэрэглэгч бүр анчин байж болно, өргөдөл, хаалганы цэс хөтлөх шаардлагагүй.',
