    allowanceIntro: 'DeHub дээр бичлэг хийх нь өдөр бүр үнэгүй бөгөөд таны ставинг тэмдэгтээр нэмэгдэж буй хязгаарын хүрээнд байдаг. Бүгд 10 текстийн бичлэг болон 1 гигабайт видео, зураг, дуу бүр өдөрт эхэлдэг. Эдгээрийн аль нэгийг давсан бол тухайн өдрийн үлдсэн хэсэг DeHub токенээр төлөгдөнө — 10c текстийн бичлэг, $2 гигабайт, зөвхөн давсан хэсэгт хураагдана.',
    allowanceIntro2: 'Текстийн бичлэгүүд ба медиа нь тусдаа багана. Нэг багана дууссан нь нөгөө баганаас хамаардаггүй, тиймээс видео байрлуулах өдөр нь бүх 10 текстийн бичлэгийг чөлөөтэй орхиж чадна. Хоёулаа UTC цагийн дунд нь дахин шинэчлэгдэнэ.',
    allowanceHowTitle: 'Төлбөрийн ажиллах арга',
