    badgeDelegationB5Desc: 'Өргөх тэмдэг гэдэг нь платформын хариуг харуулдаг бөгөөд жингээ шаталсан шатанд нь харагдах юм уу хариу үйлдэл үзүүлдэг. Энэ нь ямар ч үнэтэй зүйл агуулдаггүй: таны төлбөрийн шат, таны токен худалдан авалтын хөнгөлөлт, таны өдөр тутмын нийтлэх тэтгэмж, өөрийн төлөөлөгчийн газрууд таны доторх шүүргээс бүгдийг нь уншсан хэвээр байна.',
