    msg6: 'Ухаалаг хариулт: хэлэлцүүлгийн хоёр талын аль алиныг нь холбохоор илгээх эсвэл засах боломжтой зохиогч дор хоёр санал болгосон',
    msg7: 'Файлуудыг зураг, видео, утсаар, таблет, ширээний адилаар хавсаргах',
    superPowersDescV2: 'Супер поверсууд та бүхэнд хүрч болох нүцгэн тэмдэгийг эргүүлдэг. Өдөр бүр чиний тэмдэглэгээг нэмэгдүүлдэг бөгөөд нэг нь гэрийн тэжээлийн орой дээр байрлуулна. Баг дээш нь хүн бүрт нээлттэй бөгөөд 8 хүртэлх дансны түрийвчний хүчийг хослуулж, гишүүд бүрт нийт онгойлгогчоо цоожоор нь хангадаг. Слот нь эргэдэг: хэд хэдэн ачаалал ажиллуулах үед үзэгчдийг тэмдэгтийн эгнээгээр жигнэсэн нэгийг нь авч үздэг тул илүү өндөр түвшинг үзүүлээд хүн бүр өгөгдсөн цонхоороо авдаг.',
