    step2Desc: 'Тохиргооны → профайлд дэлгэцийн нэр, хэрэглэгчийн нэр, аватар, бүрхүүл зураг, био холбохын тулд таны нийт хүрч байгааг харуулна. Тохиргооны харагдах хэлбэрээр → загварыг сонгож, хэрэв та эргэн тойронд нь харуулахыг хүсвэл зааврын алхмыг авна уу.',
    step3Desc: 'Үүсгэх дээр дарна уу. Нийтлэл бичих, зураг нэмэх, видео эсвэл аудио нэмэх, урт хэлбэрт бичихийн тулд дугаар руу шилжих эсвэл амьдаар явах. Тусгалтыг өдөр тутмын тэтгэмж хүртэл үнэ төлбөргүй хийдэг — 10 мессеж болон тэмдэггүйгээр өдөр тутмын хэвлэл мэдээллийн хэрэгслээр гигабайт. Дараах хуудсан дээр бичсэнийг заавал оруулж болох бөгөөд дараа нь хийж болно.',
